async (page) => {
  const r = page.request; const email = `explore${Date.now()}@example.test`; const password='Passw0rd!x';
  const u = await r.post('http://localhost:3000/api/Users', {data:{email,password,passwordRepeat:password,securityQuestion:{id:1,question:'x'},securityAnswer:'a'}});
  const l = await (await r.post('http://localhost:3000/rest/user/login',{data:{email,password}})).json();
  const token = l.authentication.token, bid = l.authentication.bid;
  const h = {Authorization:`Bearer ${token}`};
  const a = await r.post('http://localhost:3000/api/Addresss',{headers:h,data:{country:'Ukraine',fullName:'Test Customer',mobileNum:501234567,zipCode:'01001',streetAddress:'1 Khreshchatyk Street',city:'Kyiv',state:'Kyiv'}});
  const c = await r.post('http://localhost:3000/api/Cards',{headers:h,data:{fullName:'Test Customer',cardNum:4111111111111111,expMonth:12,expYear:2090}});
  const cj = await c.json();
  const b = await r.post('http://localhost:3000/api/BasketItems',{headers:h,data:{ProductId:3,BasketId:bid,quantity:2}});
  const w = await r.put('http://localhost:3000/rest/wallet/balance',{headers:h,data:{balance:5,paymentId:cj.data.id}});
  await page.goto('http://localhost:3000/');
  await page.context().addCookies([{name:'token',value:token,url:'http://localhost:3000'},{name:'cookieconsent_status',value:'dismiss',url:'http://localhost:3000'}]);
  await page.evaluate(([t,b])=>{localStorage.setItem('token',t);sessionStorage.setItem('bid',String(b));},[token,bid]);
  await page.goto('http://localhost:3000/#/basket'); await page.waitForTimeout(1500);
  return JSON.stringify({email,u:u.status(),l:Object.keys(l.authentication),a:a.status(),c:c.status(),cj,b:b.status(),bj:await b.text(),w:w.status(),wj:await w.text()});
}

