async (page) => {
  await page.reload(); await page.waitForTimeout(1500);
  const counter = await page.getByRole('button',{name:'Show the shopping cart'}).innerText();
  const rowHtml = await page.locator('mat-row').first().evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').slice(0,3000));
  const total = await page.locator('#price').evaluate(e=>e.outerHTML).catch(()=> 'no #price');
  const checkout = await page.locator('#checkoutButton').evaluate(e=>e.outerHTML.slice(0,300)).catch(()=>'no');
  return JSON.stringify({counter,rowHtml,total,checkout});
}

