await (async (page) => {
  await page.locator('#checkoutButton').click(); await page.waitForTimeout(1500);
  const addr = await page.locator('app-address-select, app-address').first().evaluate(e=>e.innerText).catch(()=>'');
  const url1 = page.url();
  const rowHtml = await page.locator('mat-row').first().evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').replace(/<svg.*?<\/svg>/g,'').slice(0,1500));
