async (page) => {
  await page.locator('mat-expansion-panel-header').filter({hasText:'Add a coupon'}).click();
  await page.locator('#coupon').fill('abcdefghij');
  await page.locator('#applyCouponButton').click(); await page.waitForTimeout(1000);
  const err1 = await page.locator('app-payment').innerText();
  const errHtml = await page.getByText('Invalid coupon').evaluateAll(es=>es.map(e=>e.outerHTML));
  await page.locator('#coupon').fill('pEw8phz3Tq');
  await page.locator('#applyCouponButton').click(); await page.waitForTimeout(1000);
  const okHtml = await page.getByText('Your discount of').evaluateAll(es=>es.map(e=>e.outerHTML));
  const errAfter = await page.getByText('Invalid coupon').count();
  await page.locator('mat-row').filter({hasText:'1111'}).locator('mat-radio-button').click();
  await page.locator('button').filter({hasText:'Continue'}).click(); await page.waitForTimeout(1500);
  const sum = await page.locator('app-order-summary').innerText();
  const sumHtml = await page.locator('app-order-summary mat-card').last().evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').replace(/<svg.*?<\/svg>/g,'').replace(/ _ngcontent-[^=]*=""/g,'').slice(0,4000));
  return JSON.stringify({err1,errHtml,okHtml,errAfter,url:page.url(),sum,sumHtml},null,1);
}

