await (async (page) => {
  await page.locator('#checkoutButton').click(); await page.waitForTimeout(2000);
  const url = page.url();
  const conf = await page.locator('app-order-completion').innerText();
  const confHtml = await page.locator('app-order-completion').evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').replace(/<svg.*?</svg>/g,'').replace(/ _ngcontent-[^=]*=""/g,'').replace(/<img[^>]*>/g,'').slice(0,5000));
  const counter = await page.getByRole('button',{name:'Show the shopping cart'}).innerText();
  await page.getByRole('button',{name:'Show/hide account menu'}).click(); await page.waitForTimeout(500);
  const menu = await page.locator('.mat-mdc-menu-panel').innerText();
  const menuItems = await page.getByRole('menuitem').evaluateAll(es=>es.map(e=>`${e.getAttribute('aria-label')}|${e.innerText}`));
  await page.getByRole('menuitem').filter({hasText:'Orders & Payment'}).click(); await page.waitForTimeout(500);
  const sub = await page.getByRole('menuitem').evaluateAll(es=>es.map(e=>`${e.getAttribute('aria-label')}|${e.innerText}`));
  await page.getByRole('menuitem').filter({hasText:'Order History'}).click(); await page.waitForTimeout(1500);
  const hist = await page.locator('app-order-history').innerText();
  const histHtml = await page.locator('app-order-history').evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').replace(/<svg.*?</svg>/g,'').replace(/ _ngcontent-[^=]*=""/g,'').replace(/<img[^>]*>/g,'').slice(0,5000));
  return JSON.stringify({url,conf,confHtml,counter,menu,menuItems,sub,hist,histHtml},null,1);
})(page);
