import * as z85 from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/** Coupon code = Z85 of `<MMM><YY>-<NN>` for the month of `date` (see test-cases/README.md). */
export function couponCode(date: Date, discountPercent: number): string {
  const month = MONTHS[date.getMonth()];
  const year = String(date.getFullYear() % 100).padStart(2, '0');
  const discount = String(discountPercent).padStart(2, '0');
  const code = z85.encode(`${month}${year}-${discount}`);
  if (!code) throw new Error(`Cannot encode coupon for ${month}${year}-${discount}`);
  return code;
}

export function currentMonthCoupon(appDate: Date, discountPercent: number): string {
  return couponCode(appDate, discountPercent);
}

export function previousMonthCoupon(appDate: Date, discountPercent: number): string {
  const previous = new Date(appDate.getFullYear(), appDate.getMonth() - 1, 1);
  return couponCode(previous, discountPercent);
}

