import { APIRequestContext, expect } from '@playwright/test';
import { savedAddress, savedCard } from './test-data';

export interface Customer {
  email: string;
  password: string;
  token: string;
  basketId: number;
}

/** REST client for the Juice Shop API. Used only to prepare test preconditions. */
export class ShopApi {
  private customer?: Customer;

  constructor(private readonly request: APIRequestContext) {}

  async registerCustomer(email: string, password: string): Promise<Customer> {
    const register = await this.request.post('/api/Users', {
      data: {
        email,
        password,
        passwordRepeat: password,
        securityQuestion: { id: 1, question: 'Your eldest siblings middle name?' },
        securityAnswer: 'test',
      },
    });
    expect(register.status(), await register.text()).toBe(201);

    const login = await this.request.post('/rest/user/login', { data: { email, password } });
    expect(login.ok(), await login.text()).toBeTruthy();
    const { authentication } = await login.json();
    this.customer = { email, password, token: authentication.token, basketId: authentication.bid };
    return this.customer;
  }

  async addSavedAddress(): Promise<number> {
    const body = await this.post('/api/Addresss', savedAddress);
    return body.data.id;
  }

  async addSavedCard(): Promise<number> {
    const body = await this.post('/api/Cards', savedCard);
    return body.data.id;
  }

  async addToBasket(productName: string, quantity: number): Promise<void> {
    const productId = await this.productId(productName);
    await this.post('/api/BasketItems', {
      ProductId: productId,
      BasketId: this.requireCustomer().basketId,
      quantity,
    });
  }

  async topUpWallet(amount: number, cardId: number): Promise<void> {
    const response = await this.request.put('/rest/wallet/balance', {
      headers: this.authHeaders(),
      data: { balance: amount, paymentId: cardId },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
  }

  /** The date of the machine that runs the app, from the HTTP `Date` header. */
  async appDate(): Promise<Date> {
    const response = await this.request.get('/rest/admin/application-version');
    return new Date(response.headers()['date']);
  }

  private async productId(name: string): Promise<number> {
    const response = await this.request.get('/rest/products/search', { params: { q: name } });
    expect(response.ok()).toBeTruthy();
    const { data } = await response.json();
    const product = data.find((p: { name: string }) => p.name === name);
    if (!product) throw new Error(`Product not found: ${name}`);
    return product.id;
  }

  private async post(url: string, data: object) {
    const response = await this.request.post(url, { headers: this.authHeaders(), data });
    expect(response.ok(), `${url}: ${await response.text()}`).toBeTruthy();
    return response.json();
  }

  private authHeaders() {
    return { Authorization: `Bearer ${this.requireCustomer().token}` };
  }

  private requireCustomer(): Customer {
    if (!this.customer) throw new Error('Register a customer first');
    return this.customer;
  }
}

