import { Locator, Page } from '@playwright/test';

export class BasketPage {
  readonly rows: Locator;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;
  readonly snackBar: Locator;

  constructor(private readonly page: Page) {
    this.rows = page.locator('app-basket mat-row');
    this.totalPrice = page.locator('#price');
    this.checkoutButton = page.locator('#checkoutButton');
    this.snackBar = page.locator('mat-snack-bar-container');
  }

  async open(): Promise<void> {
    await this.page.goto('/#/basket');
  }

  row(productName: string): Locator {
    return this.rows.filter({
      has: this.page.locator('mat-cell.mat-column-product').getByText(productName, { exact: true }),
    });
  }

  quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity span');
  }

  price(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-price');
  }

  async increase(productName: string): Promise<void> {
    await this.row(productName).locator('button:has(.fa-plus-square)').click();
  }

  async decrease(productName: string): Promise<void> {
    await this.row(productName).locator('button:has(.fa-minus-square)').click();
  }

  async remove(productName: string): Promise<void> {
    await this.row(productName).locator('button:has(.fa-trash-alt)').click();
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

