async (page) => {
  await page.evaluate(()=>{localStorage.clear();sessionStorage.clear();});
  await page.context().clearCookies();
  await page.goto('http://localhost:3000/#/login'); await page.reload(); await page.waitForTimeout(1500);
  const html = await page.locator('app-login').evaluate(e=>e.outerHTML.replace(/<!--.*?-->/g,'').replace(/<svg.*?<\/svg>/g,'').replace(/ _ngcontent-[^=]*=""/g,'').replace(/ class="[^"]*"/g,'').slice(0,4000));
  await page.locator('#email').fill('nobody@example.test'); await page.locator('#password').fill('x');
  await page.locator('#loginButton').click(); await page.waitForTimeout(1000);
  const err = await page.getByText('Invalid email or password.').evaluateAll(es=>es.map(e=>e.outerHTML));
  await page.getByRole('button',{name:'Show/hide account menu'}).click(); await page.waitForTimeout(500);
  const menu = await page.getByRole('menuitem').evaluateAll(es=>es.map(e=>`${e.getAttribute('aria-label')}|${e.innerText}`));
  const del = await page.locator('app-delivery-method').count();
  return JSON.stringify({html,err,menu},null,1);
}

