import { Locator, Page } from '@playwright/test';

export class LoginPage {
  readonly title: Locator;
  readonly emailField: Locator;
  readonly emailLabel: Locator;
  readonly passwordField: Locator;
  readonly passwordLabel: Locator;
  readonly loginButton: Locator;
  readonly error: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-login');
    this.title = root.locator('h1');
    this.emailField = root.locator('#email');
    this.emailLabel = root.locator('label[for="email"]');
    this.passwordField = root.locator('#password');
    this.passwordLabel = root.locator('label[for="password"]');
    this.loginButton = root.locator('#loginButton');
    this.error = root.getByRole('alert');
  }

  async open(): Promise<void> {
    await this.page.goto('/#/login');
  }

  async login(email: string, password: string): Promise<void> {
    await this.emailField.fill(email);
    await this.passwordField.fill(password);
    await this.loginButton.click();
  }
}

