import { Locator, Page } from '@playwright/test';

/** Rows of the selection tables on the checkout pages have a radio button in the first cell. */
function selectRow(page: Page, rows: Locator, text: string): Promise<void> {
  return rows.filter({ hasText: text }).locator('mat-radio-button').click();
}

export class AddressSelectPage {
  readonly title: Locator;
  readonly rows: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.locator('app-address-select h1');
    this.rows = page.locator('app-address-select mat-row');
    this.continueButton = page.locator('app-address-select button').filter({ hasText: 'Continue' });
  }

  address(text: string): Locator {
    return this.rows.filter({ hasText: text });
  }

  async selectAddressAndContinue(text: string): Promise<void> {
    await selectRow(this.page, this.rows, text);
    await this.continueButton.click();
  }
}

export class DeliveryMethodPage {
  readonly title: Locator;
  readonly rows: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.locator('app-delivery-method h1').filter({ hasText: 'Choose a delivery speed' });
    this.rows = page.locator('app-delivery-method mat-row');
    this.continueButton = page.locator('app-delivery-method button').filter({ hasText: 'Continue' });
  }

  method(name: string): Locator {
    return this.rows.filter({ hasText: name });
  }

  methodPrice(name: string): Locator {
    return this.method(name).locator('mat-cell.mat-column-Price');
  }

  async selectMethodAndContinue(name: string): Promise<void> {
    await selectRow(this.page, this.rows, name);
    await this.continueButton.click();
  }
}

export class PaymentPage {
  readonly title: Locator;
  readonly cardRows: Locator;
  readonly couponPanel: Locator;
  readonly couponField: Locator;
  readonly redeemButton: Locator;
  readonly couponError: Locator;
  readonly couponConfirmation: Locator;
  readonly walletBalance: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-payment');
    this.title = root.locator('h1');
    this.cardRows = root.locator('mat-row');
    this.couponPanel = root.locator('mat-expansion-panel-header').filter({ hasText: 'Add a coupon' });
    this.couponField = root.locator('#coupon');
    this.redeemButton = root.locator('#applyCouponButton');
    this.couponError = root.locator('.error');
    this.couponConfirmation = root.locator('.confirmation').filter({ hasText: 'Your discount of' });
    this.walletBalance = root.getByText(/^Wallet Balance/);
    this.continueButton = root.locator('button').filter({ hasText: 'Continue' });
  }

  card(lastDigits: string): Locator {
    return this.cardRows.filter({ hasText: lastDigits });
  }

  payWithWalletButton(amount: string): Locator {
    return this.page.locator('app-payment button').filter({ hasText: `Pay ${amount}` });
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.click();
    await this.couponField.waitFor();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
    await this.redeemButton.click();
  }

  async selectCardAndContinue(lastDigits: string): Promise<void> {
    await selectRow(this.page, this.cardRows, lastDigits);
    await this.continueButton.click();
  }
}

export class OrderSummaryPage {
  readonly root: Locator;
  readonly deliveryAddress: Locator;
  readonly paymentMethod: Locator;
  readonly placeOrderButton: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-summary');
    this.deliveryAddress = this.root.locator('mat-card').filter({ hasText: 'Delivery Address' }).first();
    this.paymentMethod = this.root.locator('mat-card').filter({ hasText: 'Payment Method' }).first();
    this.placeOrderButton = page.getByRole('button', { name: 'Complete your purchase' });
  }

  /** Value of a line of the `Order Summary` table, for example `Items` or `Total Price`. */
  line(label: string): Locator {
    return this.root
      .locator('tr')
      .filter({ has: this.page.locator('td.label').getByText(label, { exact: true }) })
      .locator('td.price');
  }
}

export class OrderCompletionPage {
  readonly root: Locator;
  readonly title: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-completion');
    this.title = this.root.locator('h1');
  }

  quantity(productName: string): Locator {
    return this.root
      .locator('mat-row')
      .filter({ has: this.page.locator('mat-cell.mat-column-product').getByText(productName, { exact: true }) })
      .locator('mat-cell.mat-column-quantity');
  }

  /**
   * The totals table has the labels in one column and the values in the next column,
   * so the value of a label is the cell with the same row index.
   */
  async line(label: string): Promise<Locator> {
    const labels = await this.root.locator('mat-footer-cell.mat-column-quantity td').allInnerTexts();
    const index = labels.map((l) => l.trim()).indexOf(label);
    if (index < 0) throw new Error(`No line "${label}" in the order summary: ${labels.join(', ')}`);
    return this.root.locator('mat-footer-cell.mat-column-total-price td').nth(index);
  }
}

export class OrderHistoryPage {
  readonly root: Locator;
  readonly orders: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-history');
    this.orders = this.root.locator('.table-container');
  }

  order(orderId: string): Locator {
    return this.orders.filter({ hasText: `#${orderId}` });
  }

  /** Value under a heading of an order, for example `Total Price` or `Bonus`. */
  orderField(order: Locator, label: string): Locator {
    return order
      .locator('.heading .col-vertical')
      .filter({ has: this.page.getByText(label, { exact: true }) })
      .locator('div')
      .nth(1);
  }

  quantity(order: Locator, productName: string): Locator {
    return order
      .locator('mat-row')
      .filter({ has: this.page.locator('mat-cell.mat-column-product').getByText(productName, { exact: true }) })
      .locator('mat-cell.mat-column-quantity');
  }
}

export class WalletPage {
  readonly balance: Locator;

  constructor(page: Page) {
    this.balance = page.locator('app-wallet .confirmation');
  }
}

