import { expect, test } from './support/fixtures';
import { uniqueEmail } from './support/test-data';

test('TC-01: Login with a valid and an invalid password', async ({ page, api, shop }) => {
  const email = uniqueEmail('tc01');
  const password = 'Passw0rd!tc01';
  const wrongPassword = `${password}x`;
  await api.registerCustomer(email, password);
  const { loginPage, navBar } = shop;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
    await expect(loginPage.title).toHaveText('Login');
    await expect(loginPage.emailField).toBeVisible();
    await expect(loginPage.emailLabel).toHaveText('Email');
    await expect(loginPage.passwordField).toBeVisible();
    await expect(loginPage.passwordLabel).toHaveText('Password');
    await expect(loginPage.loginButton).toHaveText(/Log in/);
  });

  await test.step('2. Log in with the wrong password', async () => {
    await loginPage.login(email, wrongPassword);
    await expect(loginPage.error).toHaveText('Invalid email or password.');
    await expect(page).toHaveURL(/#\/login$/);
  });

  await test.step('3. Open the account menu', async () => {
    await navBar.openAccountMenu();
    await expect(navBar.menuItem('Login')).toBeVisible();
    await expect(navBar.accountMenu).not.toContainText(email);
  });

  await test.step('4. Close the menu and log in with the correct password', async () => {
    await navBar.closeMenu();
    await loginPage.login(email, password);
    await expect(page).toHaveURL(/#\/search$/);
  });

  await test.step('5. Open the account menu', async () => {
    await navBar.openAccountMenu();
    await expect(navBar.accountMenu).toContainText(email);
    await expect(navBar.menuItem('Logout')).toBeVisible();
  });
});

