import { expect, loginInBrowser, test } from './support/fixtures';
import { products, uniqueEmail } from './support/test-data';

test('TC-02: Add a product to the basket', async ({ page, api, shop, baseURL }) => {
  const product = products.eggfruitJuice;
  const customer = await api.registerCustomer(uniqueEmail('tc02'), 'Passw0rd!tc02');
  await loginInBrowser(page, customer, baseURL!);
  const { productList, navBar, basket } = shop;

  await test.step('1. Open the product list', async () => {
    await productList.open();
    await expect(productList.productName(product.name)).toBeVisible();
    await expect(productList.productPrice(product.name)).toHaveText(product.price);
    await expect(productList.addToBasketButton(product.name)).toBeVisible();
    await expect(navBar.basketCounter).toHaveText('0');
  });

  await test.step('2. Add the product to the basket', async () => {
    await productList.addToBasket(product.name);
    await expect(productList.snackBar).toContainText(`Placed ${product.name} into basket.`);
    await expect(navBar.basketCounter).toHaveText('1');
  });

  await test.step('3. Open the basket', async () => {
    await navBar.openBasket();
    await expect(page).toHaveURL(/#\/basket$/);
    await expect(basket.rows).toHaveCount(1);
    await expect(basket.row(product.name)).toBeVisible();
    await expect(basket.quantity(product.name)).toHaveText('1');
    await expect(basket.price(product.name)).toHaveText(product.price);
  });

  await test.step('4. Read the basket total', async () => {
    await expect(basket.totalPrice).toHaveText('Total Price: 8.99¤');
  });
});

