import { expect, loginInBrowser, test } from './support/fixtures';
import { products, uniqueEmail } from './support/test-data';

test('TC-03: Change the quantity and remove a product in the basket', async ({ page, api, shop, baseURL }) => {
  const productA = products.raspberryJuice;
  const productB = products.eggfruitJuice;
  const customer = await api.registerCustomer(uniqueEmail('tc03'), 'Passw0rd!tc03');
  await api.addToBasket(productA.name, 1);
  await api.addToBasket(productB.name, 1);
  await loginInBrowser(page, customer, baseURL!);
  const { basket, navBar } = shop;

  await test.step('1. Open the basket', async () => {
    await basket.open();
    await expect(basket.rows).toHaveCount(2);
    await expect(basket.quantity(productA.name)).toHaveText('1');
    await expect(basket.quantity(productB.name)).toHaveText('1');
    await expect(basket.totalPrice).toHaveText('Total Price: 13.98¤');
    await expect(navBar.basketCounter).toHaveText('2');
  });

  await test.step('2. Increase the quantity of product A', async () => {
    await basket.increase(productA.name);
    await expect(basket.quantity(productA.name)).toHaveText('2');
    await expect(basket.totalPrice).toHaveText('Total Price: 18.97¤');
    await expect(navBar.basketCounter).toHaveText('3');
  });

  await test.step('3. Decrease the quantity of product A', async () => {
    await basket.decrease(productA.name);
    await expect(basket.quantity(productA.name)).toHaveText('1');
    await expect(basket.totalPrice).toHaveText('Total Price: 13.98¤');
    await expect(navBar.basketCounter).toHaveText('2');
  });

  await test.step('4. Decrease the quantity of product A again', async () => {
    const update = page.waitForResponse((r) => r.url().includes('/api/BasketItems/') && r.request().method() === 'PUT');
    await basket.decrease(productA.name);
    await update;
    await expect(basket.row(productA.name)).toBeVisible();
    await expect(basket.quantity(productA.name)).toHaveText('1');
    await expect(basket.totalPrice).toHaveText('Total Price: 13.98¤');
  });

  await test.step('5. Remove product A', async () => {
    await basket.remove(productA.name);
    await expect(basket.row(productA.name)).toHaveCount(0);
    await expect(basket.quantity(productB.name)).toHaveText('1');
    await expect(basket.totalPrice).toHaveText('Total Price: 8.99¤');
    await expect(navBar.basketCounter).toHaveText('1');
  });
});

