import { chooseDelivery } from './support/checkout-flow';
import { couponCode } from './support/coupon';
import { expect, loginInBrowser, test } from './support/fixtures';
import { products, savedAddress, uniqueEmail } from './support/test-data';

test('TC-05: Valid coupon on the payment step', async ({ page, api, shop, baseURL }) => {
  const customer = await api.registerCustomer(uniqueEmail('tc05'), 'Passw0rd!tc05');
  await api.addSavedAddress();
  await api.addSavedCard();
  await api.addToBasket(products.eggfruitJuice.name, 2);
  const coupon = couponCode(await api.appDate(), 10);
  await loginInBrowser(page, customer, baseURL!);
  const { basket, addressSelect, deliveryMethod, payment, orderSummary } = shop;

  await test.step('1. Open the basket and click Checkout', async () => {
    await basket.open();
    await basket.checkout();
    await expect(addressSelect.title).toHaveText('Select an address');
    await expect(addressSelect.address(savedAddress.streetAddress)).toContainText(savedAddress.fullName);
  });

  await test.step('2. Select the saved address and continue', async () => {
    await addressSelect.selectAddressAndContinue(savedAddress.streetAddress);
    await expect(deliveryMethod.title).toBeVisible();
    await expect(deliveryMethod.method('One Day Delivery')).toContainText('0.99¤');
    await expect(deliveryMethod.method('Fast Delivery')).toContainText('0.50¤');
    await expect(deliveryMethod.method('Standard Delivery')).toContainText('0.00¤');
  });

  await test.step('3. Select One Day Delivery and continue', async () => {
    await chooseDelivery(shop, 'One Day Delivery');
    await expect(payment.card('1111')).toContainText('Test Customer');
    await expect(payment.couponPanel).toBeVisible();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
    await payment.openCouponPanel();
    await payment.redeemCoupon(coupon);
    await expect(payment.couponConfirmation).toHaveText('Your discount of 10% will be applied during checkout.');
  });

  await test.step('5. Select the saved card and continue', async () => {
    await payment.selectCardAndContinue('1111');
    await expect(orderSummary.line('Items')).toHaveText('17.98¤');
    await expect(orderSummary.line('Delivery')).toHaveText('0.99¤');
    await expect(orderSummary.line('Promotion')).toHaveText('1.80¤');
    await expect(orderSummary.line('Total Price')).toHaveText('17.17¤');
  });
});

