import { checkoutToDelivery, chooseDelivery } from './support/checkout-flow';
import { expect, loginInBrowser, test } from './support/fixtures';
import { products, uniqueEmail } from './support/test-data';

test('TC-08: Payment with the wallet', async ({ page, api, shop, baseURL }) => {
  const customer = await api.registerCustomer(uniqueEmail('tc08'), 'Passw0rd!tc08');
  await api.addSavedAddress();
  const cardId = await api.addSavedCard();
  await api.addToBasket(products.eggfruitJuice.name, 1);
  await api.topUpWallet(5, cardId);
  await loginInBrowser(page, customer, baseURL!);
  const { navBar, payment, orderSummary, orderCompletion, orderHistory, wallet } = shop;
  const payButton = payment.payWithWalletButton('8.99¤');

  // Part 1: the wallet holds less than the order total.

  await test.step('1. Checkout with the saved address', async () => {
    await checkoutToDelivery(shop);
  });

  await test.step('2. Select Standard Delivery and continue', async () => {
    await chooseDelivery(shop, 'Standard Delivery');
    await expect(payment.walletBalance).toHaveText('Wallet Balance 5.00');
    await expect(payButton).toBeVisible();
  });

  await test.step('3. The wallet button is disabled', async () => {
    await expect(payButton).toBeDisabled();
  });

  await test.step('4. No order in the order history', async () => {
    await navBar.openOrderHistory();
    await expect(page.getByText('You have not placed any orders yet.')).toBeVisible();
  });

  await test.step('5. The wallet balance is 5.00', async () => {
    await navBar.openDigitalWallet();
    await expect(wallet.balance).toHaveText('5.00');
  });

  // Part 2: the wallet holds exactly the order total.
  await api.topUpWallet(3.99, cardId);

  await test.step('6. Checkout again', async () => {
    await checkoutToDelivery(shop);
    await chooseDelivery(shop, 'Standard Delivery');
    await expect(payment.walletBalance).toHaveText('Wallet Balance 8.99');
    await expect(payButton).toBeEnabled();
  });

  await test.step('7. Pay with the wallet', async () => {
    await payButton.click();
    await expect(orderSummary.root).toContainText('Digital Wallet');
    await expect(orderSummary.line('Total Price')).toHaveText('8.99¤');
  });

  await test.step('8. Place the order', async () => {
    await orderSummary.placeOrderButton.click();
    await expect(orderCompletion.title).toHaveText('Thank you for your purchase!');
  });

  await test.step('9. The wallet balance is 1.00', async () => {
    await navBar.openDigitalWallet();
    await expect(wallet.balance).toHaveText('1.00');
  });

  await test.step('10. One order in the order history', async () => {
    await navBar.openOrderHistory();
    await expect(orderHistory.orders).toHaveCount(1);
    const order = orderHistory.orders.first();
    await expect(orderHistory.orderField(order, 'Total Price')).toHaveText('8.99¤');
    await expect(orderHistory.orderField(order, 'Bonus')).toHaveText('1');
  });
});

